/* @prim:begin 69-proof-lockup */
.plk { container-type: inline-size; display: grid; gap: var(--sp-2, 16px); margin: 0; min-width: 0; }
.plk-kick { margin: 0; font-size: var(--fs-body); font-style: italic; font-weight: 400; line-height: 1.5; color: var(--text); text-wrap: pretty; }
.plk-cells { display: grid; grid-template-columns: minmax(0, 1fr); margin: 0; padding: 0; list-style: none; border: 1px solid var(--border); border-radius: var(--ds-r-sm); background: var(--glass, var(--surface)); box-shadow: var(--bevel, 0 0 0 transparent), var(--lift, 0 0 0 transparent); }
.plk-cell { display: grid; align-content: start; gap: 4px; min-width: 0; padding: 14px 16px; }
.plk-cell + .plk-cell { border-top: 1px solid var(--border); }
.plk-lab { font-family: var(--ds-font-mono); font-size: var(--fs-label); font-weight: 700; line-height: 1.2; letter-spacing: 0.1em; text-transform: uppercase; color: var(--text-secondary); }
.plk-fig { font-family: var(--ds-font-mono); font-size: var(--fs-display); font-weight: 700; line-height: 1.15; letter-spacing: -0.01em; font-variant-numeric: tabular-nums; color: var(--cyan); overflow-wrap: anywhere; }
@container (min-width: 40rem) { .plk-fig { font-size: min(var(--fs-display), 2.9cqi); white-space: nowrap; } }
.plk-cap { font-size: var(--fs-body); line-height: 1.45; color: var(--text-secondary); text-wrap: pretty; }
.plk-close { margin: 0; font-size: var(--fs-body); font-weight: 600; line-height: 1.5; color: var(--text); text-wrap: pretty; }
@container (min-width: 40rem) { .plk-cells { grid-template-columns: none; grid-auto-flow: column; grid-auto-columns: minmax(0, 1fr); } .plk-cell + .plk-cell { border-top: 0; border-left: 1px solid var(--border); } }
@media print { .plk { break-inside: avoid; } .plk-cells { background: none; box-shadow: none; } .plk-fig { font-size: var(--fs-headline); color: var(--text); } }
/* @prim:end 69-proof-lockup */

